                "Что это ещё за разряженная барыня с моими глазами?! Спрятала верные клинки под полой пальто и пускаешь призраков вместо честной рубки?!",
                "Тише, дорогая моя прошлая тень~ Зачем грызть железный поводок Сиракуз зубами, когда можно перерезать нити всего кукольного театра одним щелчком?",
