                "Клянусь всеми масками карнавала, даже самый безумный шут Сиракуз выглядит скучным бухгалтером рядом с вами, Голд Шип!",
                "МАЭСТРО ВОЛЧИЦА! Я подготовила сольный номер для твоего театра: прыжок через горящий обруч с якорем в зубах!",
