                "О боже, неужели я со стороны выглядела НАСТОЛЬКО шумной выскочкой с карточным пультом?! Какой позор перед предками...",
                "Эй, слышь, я вообще-то само очарование с тротилом! Небось скучаешь по временам, когда можно было просто заминировать дверь и смыться?",
                "Скучаю каждую проклятую планёрку в Казделе, мелкая я! Поэтому заткнись и давай взорвём эту долину в два ствола!");

            AddPair(dict, "w_wisadel", "w_arknights",
                "Только не говори, что ты снова спрятала противопехотную мину под кресло капитана на мостике, прошлая я.",
