                "Смотри и учись: «Взрывной Рассвет» плюс твой D12 — делаем из этого сектора лунный кратер!");

            AddPair(dict, "w_wisadel", "gold_ship",
                "Эй, белая кобыла, мой ревенант клянётся, что за три тысячи лет истории Терры не видел существа дурнее тебя!",
