                "Обгонишь снаряд?! Давай проверим: стреляю по боссу у Телепорта — если прибежишь раньше взрыва, ставлю ящик якисобы!",
                "НА СТАРТ — ПЛИ! Снаряд летит по дуге, а Голши срезает сквозь текстуры реальности!");

            AddPair(dict, "w_wisadel", "pushnoy",
                "Эй, рок-физик, старики в моей установке интересуются: откуда у землянина в гитаре столько чистого грома без единого кристалла Ориджиниума?!",
                "Передай уважаемым предкам Каздела: электромагнитная индукция Фарадея и ламповый перегруз творят чудеса безо всякой магии!",
                "Ха! Слышали, ворчуны, вас уделал школьный учебник физики! Врубай свой усилитель, Пушной, дадим залп под барабаны!",
                "ОСАДНАЯ АРТИЛЛЕРИЯ ПОД ХЭВИ-МЕТАЛ! Как говорил классик — любо-дорого посмотреть!");

            AddPair(dict, "w_wisadel", "freddy",
                "Слушай, железный медведь, мои ревенанты говорят, что твоя жестянка фонит остаточными душами почти как старая кузница Каздела.",
                "Хар-хар-хар! Фирменный секрет производства Fazbear Entertainment, госпожа Председатель — мы называем это «эффектом присутствия»!",
                "Жуткая у вас контора, ничего не скажешь. Пугай монстров внизу своим маршем, а я накрою их сверху обелисками!",
                "Принято! Тьма снизу, багровый рассвет сверху — идеальный финал ночной смены!");

            AddPair(dict, "w_wisadel", "steve",
                "Слушай, квадратный прораб, нам бы в отстраиваемый Каздел десяток таких каменщиков, как ты — город бы стоял за неделю!",
