            AddPair(dict, "w_wisadel", "jotaro",
                "Удобная у тебя способность, Куджо: ты ставишь мир на паузу, а мои пилоны за это время спокойно сводят прицелы в одну точку.",
                "Главное — предупреждай за секунду до залпа, Вишадель. Оглохнуть от твоих обелисков после возобновления времени я не горю желанием.",
                "Не ворчи, для ближнего бойца я оставляю аккуратную зону безопасности в три метра! Ну... почти всегда~",
