            AddPair(dict, "w_wisadel", "haze",
                "Знаешь, агент Хейз, с тех пор как в моём оружии поселились духи предков, у меня даже во сне идёт военный совет на повышенных тонах.",
                "Я слышу этот тысячелетний спор вокруг вас, Вишадель. Хотите, на время орбитальной стоянки я приглушу их голоса сонной вуалью?",
