            AddPair(dict, "w_wisadel", "dmc_trio",
                "В прошлый раз ты блокировал мои гранаты одной ладонью, охотник в красном — ну-ка посмотрим, как твой Royal Guard переварит осадный обелиск!",
                "Ого, дамочка обзавелась пушкой размером с мой диван в офисе! Если выдержу на идеальном тайминге — угощаешь пиццей!",
                "Ха! Да если ты отразишь залп «Тени Восставших» без царапины, мои ревенанты сами испекут тебе пиццу на плазменной тяге!",
                "Договорились, свидетели записали! Подавай свой главный калибр на арене!");

            AddPair(dict, "w_wisadel", "sanabi",
                "Эй, Генерал, твоя мелкая хакерша умудрилась взломать интерфейс наведения моего древнего ревенанта и нарисовала там смайлик!",
                "Мари: Хи-хи, дедушка внутри пушки ругался на старом шифре, но мы с ним быстро подружились! — Генерал: Мари! Немедленно верни штатную прошивку!",
                "Да оставь ты, Генерал! Старик в пушке впервые за век доволен — говорит, у девчонки хватка настоящего осадного мастера!",
                "Генерал: ...Если дух предков не возражает, работаем по наводке Мари. — Мари: УРА, ТЕПЕРЬ У НАС ЕСТЬ ОРБИТАЛЬНЫЙ СМАЙЛИК!");

            AddPair(dict, "w_wisadel", "sol_ky",
                "Король Иллирии собственной персоной! Спорим, ваши чистенькие рыцари упали бы в обморок от методов правления в Казделе?",
                "Каждая страна проходит свой суровый путь к миру, госпожа Вишадель. Я вижу, что за дерзостью вы всерьёз печётесь о своём народе.",
                "Тц... Перестань смотреть так понимающе, ваше величество, у меня от честных монархов оскомина начинается!",
