            AddPair(dict, "dmc_nero", "commando",
                "Эй, пехотинец, неплохо кувыркаешься с двумя стволами! Хочешь, попрошу Нико прикрутить бензиновый ускоритель и к твоей броне?",
                "Спасибо, Неро, но если у меня за спиной взревёт мотоциклетный мотор на жидком топливе, скафандр потеряет герметичность.",
