            AddPair(dict, "dmc_nero", "buzz",
                "Здорово, космический рейнджер! Слушай, а у тебя в нарукавнике тоже сменные боевые насадки, как мои Devil Breaker'ы?",
                "В моём скафандре встроен штатный лазер, крюк и бортовой журнал, кадет Неро! И рука, к счастью, не отстёгивается при взрыве!",
