                "Погоди-ка, железный! У тебя ТОЖЕ сменные разноцветные руки — синяя для парирования, красная взрывная и зелёная с тросом?!",
                "[СОВПАДЕНИЕ КОНСТРУКЦИИ ПОДТВЕРЖДЕНО // ВАШИ ПРОТЕЗЫ ХРУПКИЕ, НО ИМЕЮТ ВЫСОКИЙ СТИЛЬ.]",
                "Хрупкие?! Да я этим крюком «Snatch» каменных титанов за шкирку через полполя швыряю! Щас устроим соревнование рук!",
                "[ВЫЗОВ ПРИНЯТ: СЧЁТЧИК СТИЛЯ СИНХРОНИЗИРОВАН НА РАНГ SSS.]");

            AddPair(dict, "dmc_nero", "sol",
                "Ого, меч с выхлопной трубой и зажиганием прямо в гарде! Слушай, Сол, ты случайно не у того же мастера ковался, что и Орден Меча?!",
                "Сам собрал в гараже на коленке, пацан. Зато твой мотор на рукояти рычит как добрый восьмицилиндровый движок — уважаю.",
                "Система Exceed на три такта! Выкручиваешь ручку газа в момент удара — и сталь идёт сквозь демонов как раскалённый нож!",
                "Хех! Наш человек — меньше пафосной болтовни, больше огня и крутящего момента!");

            AddPair(dict, "dmc_nero", "gwen",
                "Эй, Гвен, прости за нескромную просьбу... не зашьёшь мне правый рукав на синей куртке? Вечно рвётся, когда меняю протезы!",
                "С радостью, Неро! У тебя очень стильная куртка, я сделаю аккуратную потайную застёжку, чтобы рука менялась без разрывов!",
                "Серьёзно?! Кирие обрадуется, что я впервые вернусь из командировки не в лохмотьях! С меня должок в бою!",
                "Договорились! Вместе искрошим всех чудовищ на аккуратные ленточки!");

            AddPair(dict, "dmc_nero", "enforcer",
                "Знавал я рыцарей в белых доспехах со щитами у себя в Фортуне — те были ещё те фанатики, но ты вроде мужик надёжный, Силовик.",
