            AddPair(dict, "dmc_nero", "scout",
                "Слышь, бородач, у тебя двустволка, крюк и привычка носиться сломя голову — да мы с тобой будто из одного гаража вышли!",
                "Аха-ха! А твоя «Синяя Роза» стреляет сразу ДВУМЯ крупнокалиберными пулями с одного спуска?! Дай пожать твою железную лапу, парень!",
