            AddPair(dict, "dmc_nero", "m4a1",
                "Командир M4A1, если твоим клонам нужно вытащить тяжёлый сундук из-под носа у босса — свисти, перетяну титана на себя крюком!",
                "Благодарю за инициативу, Неро. Только старайтесь не отрываться от группы на реактивном кулаке слишком далеко.",
