            AddPair(dict, "dmc_nero", "medic",
                "Так, док, сразу предупреждаю: к моей правой руке со скальпелем не подходить, она уже отрастала заново, больше экспериментов не хочу!",
                "КАК ЭТО «ОТРАСТАЛА ЗАНОВО»?! Демоническая регенерация конечностей?! Юноша, всего один мазок ткани для моей коллекции, умоляю!",
