                "Ох, молодёжь пошла пугливая! Ладно, заряжаю Крицкриг — рубите во славу медицины!");

            AddPair(dict, "dmc_nero", "aigis",
                "Слушай, Айгис, Нико бы в обморок рухнула от восторга: живая девушка-андроид с пулемётами в пальцах И собственным духом-рыцарем!",
                "Анализ показывает, что ваш механический протез создан с огромным мастерством и заботой о вас, Неро!",
                "Хех, «с заботой» — Нико за каждую сломанную руку с меня три шкуры дерёт и окурками кидается! Но мастер она гениальный!",
                "Значит, это особая человеческая форма дружбы! Буду рада прикрыть вас в бою!");

            AddPair(dict, "dmc_nero", "reimu",
                "Слушай, жрица, ты гоняешь духов бумажками и палкой, а денег вечно в обрез — прямо как у Данте в агентстве до встречи с Нико!",
                "Если знаешь секрет, как заставить спасённых жителей платить по счетам вовремя — выкладывай немедленно, парень!",
