                "Гениальная бизнес-модель! Надо срочно завести боевой фургон при Храме Хакурей!");

            AddPair(dict, "dmc_nero", "mindustry",
                "Ух ты, летающий сборщик заводов! Слушай, Гамма, а ты можешь печатать мне запасные руки «Gerbera» прямо посреди боя из кремния?!",
                "[ЧЕРТЁЖ DEVIL BREAKER ПРОСКАНИРОВАН. ТРЕБУЕТСЯ 45 КРЕМНИЯ И 20 ТИТАНА НА ЕДИНИЦУ. ЗАПУСКАЮ СБОРОЧНЫЙ ЦЕХ.]",
                "БЕСКОНЕЧНЫЙ ЗАПАС ПРОТЕЗОВ БЕЗ ВОРЧАНИЯ НИКО?! Гамма, ты лучший робот в этой галактике!",
                "[ПОЛЬЗОВАТЕЛЬ НЕРО УДОВЛЕТВОРЁН. ПРОШУ РАЗБИВАТЬ ВРАГОВ СТРОГО ПЕРЕД ЛИНИЕЙ ТУРЕЛЕЙ.]");

            AddPair(dict, "dmc_nero", "slark",
                "Эй, скользкий, думаешь, раз ушёл в чёрное облако — можно безнаказанно таскать предметы из-под моего носа?!",
                "Хе-хе, молодой да горячий! Пока ты газуешь своим мечом на всю округу, тихая рыба уже сняла сливки со всех сундуков!",
