                "Ладно-ладно, не кипятись, поделюсь трофеями по-честному — в бою твоя дурь нам на руку!");

            AddPair(dict, "dmc_nero", "tidehunter",
                "Вот это здоровый кракен на двух ногах! Погоди, да ты почти как демонический Дагон, только вместо жаб метаешь корабельный якорь!",
                "Не путай чемпиона Маэлрона со всякой болотной нечистью, мальчишка с тарахтящим мечом!",
                "Проверим в деле: схвачу твой якорь призрачной лапой и закручу тебя волчком прямо в гущу титанов — рискнёшь?!",
                "БУА-ХА-ХА! Если у тебя хватит силёнок поднять мой вес — крути хоть до самого горизонта!");

            AddPair(dict, "dmc_nero", "freeman",
                "Уважаю, док: никакой магии Спарды, никаких демонических рук — чистая физика, монтировка и стальные нервы!",
                "... *оценивающе слушает ровный рык двигателя на мече Неро и показывает жест «отличная тяга»*",
                "Хочешь крутануть ручку Exceed? Осторожно, отдача на третьей передаче выбивает плечо с непривычки!",
                "... *уверенно включает сервоприводы костюма HEV и легко выжимает полный красный накал лезвия с первого раза!*");

            AddPair(dict, "dmc_nero", "dante",
                "Услышал в коридоре «Данте, к отчёту!» — уже хотел отвесить старику подзатыльник, а тут человек с горящими часами!",
                "<Тик-так...> (Счастливый ты человек, Неро, если слово «Данте» ассоциируется у тебя с шутками, а не со сверхурочной болью!)",
                "Ха! Да мой дядюшка Данте тоже мастер свалить всю грязную работу на молодёжь! Держись за мной, часовой босс, прорвёмся!",
                "<Тик-так-тик!> (Наконец-то молодой боец, который рвётся вперёд И при этом слушает команды!)");

            AddPair(dict, "dmc_nero", "cheburashka",
                "Эй, осторожнее под ногами, мелкий ушастик! Тут кругом железки и искры от меча летят, как ты вообще на боевой корабль попал?!",
                "В ящике с апельсинами, дядя Неро! Не переживайте за меня, у нас с Кирие... ой, то есть с Геной есть большой приют для друзей!",
                "Хех... Кирие от тебя и правда была бы без ума, у нас дома вечно полон стол детворы. Держись рядом, в обиду не дам!",
                "Спасибо, Неро! А если на вас нападёт огромный каменный титан, мой Крокодил Гена стукнет его вместе с вашим призрачным крылом!");

            AddPair(dict, "dmc_nero", "ahri",
                "Э-эй, полегче с лисьими подмигиваниями и сердечками, дамочка! Меня дома ждёт Кирие, так что эти фокусы мимо кассы!",
                "Хи-хи, как мило ты краснеешь и сразу хватаешься за воротник, юный охотник~ Не бойся, чужое счастье я только берегу.",
                "Кхм... Никто не краснеет, просто от мотора меча жарко! Ладно, приманивай монстров в кучу, я впечатаю их в землю!",
                "Верное сердце бьёт сильнее любого заклинания~ Лети вперёд, рыцарь Фортуны.");

            AddPair(dict, "dmc_nero", "lappland",
                "Бешеная ухмылка, два меча и привычка кидаться на всё, что шевелится... Клянусь, ты бы спелась с моим ненормальным семейством!",
                "Аха-ха! А мне нравится, как яростно ревёт бензин в твоём клинке, мальчишка — никакой чопорной фехтовальной скуки!",
                "В уличной драке главное — вбить врага в асфальт раньше, чем он моргнёт! Спорим, я наберу ранг SSS быстрее тебя?!",
                "Охо-хо, смелая ставка! Проигравший чистит чужие клинки от запекшейся смолы!");

            AddPair(dict, "dmc_nero", "w_arknights",
                "Слышь, подрывница, мы с Нико знаем толк в хорошем бабахе, но лепить C4 на мой ракетный кулак «Punch Line» — это перебор!",
                "Да ладно тебе ломаться, пацан! Представь: летит твой реактивный кулак, крутится вокруг босса — и БУМ на весь кратер!~",
                "...Чёрт возьми, а ведь звучит реально круто! Ладно, лепи одну карточку на кастет, проверим на каменном големе!",
                "ХА! Я знала, что под грозным видом скрывается наш человек!");

            AddPair(dict, "dmc_nero", "gold_ship",
                "ЭЙ! Ты только что обогнала мой летящий реактивный протез пешком, да ещё и корчила ему рожи на бегу?!",
                "ТВОЯ РАКЕТА ИДЁТ НА ВТОРОМ МЕСТЕ, ЮНОША! Поддай бензину в свой меч, а то Голд Шип заберёт все трофеи у Телепорта!",
                "Ах так?! Щас выжму три заряда Exceed и включу крылья — посмотрим, чьи пятки будут сверкать впереди!",
                "ГОНКА ВЕКА: ПОЛУДЕМОН С МОТОРОМ ПРОТИВ ЧЕМПИОНКИ АРИМА КИНЭН! Погнали!");

            AddPair(dict, "dmc_nero", "pushnoy",
                "Мужик, когда ты в кают-компании врубил тяжёлый рифф на гитаре, у меня сам собой палец начал газовать ручку меча в такт!",
                "Потому что ритм сто сорок ударов и рёв мотора — это родные братья по акустике, Неро! Кстати, наушники у тебя отличные!",
                "Никогда не выхожу на охоту без правильного трека в ушах! Скинешь пару своих боевиков перед высадкой?!",
                "Да я тебе живьём сыграю прямо на поле боя через катушку Теслы — весь этап будет трясти басами!");

            AddPair(dict, "dmc_nero", "freddy",
                "Нико собирала всякую чертовщину из металлолома, но говорящий медведь из пиццерии с челюстью-капканом — это уже перебор!",
                "Хар-хар-хар! Не сердитесь, молодой человек, в кулинарном уголке Fazbear всегда рады шумным компаниям!",
                "Смотри у меня, плюшевый: вздумаешь клацать зубами в темноте рядом со своими — вставлю протез «Helter Skelter» прямо в пасть!",
                "Бззт... Заказ принят вежливо и без очереди! Идём пугать исключительно лемурийцев!");

            AddPair(dict, "dmc_nero", "steve",
                "Ты выковал алмазный меч двумя ударами молотка на деревянном пеньке без горна и чертежей?! Нико сейчас лопнет от зависти!",
                "Два алмаза и одна палка на верстаке — ничего сложного. Могу дать огненный аспект, будет жечь как твой мотор.",
                "И никаких счетов на десять тысяч красных орбов за починку?! Стив, переезжай к нам в фургон, озолотимся!",
                "В фургоне сундуки растрясёт, но походную кузницу перед высадкой организую.");

            AddPair(dict, "dmc_nero", "jotaro",
                "Подожди-ка... Когда я выпускаю призрачные руки своего Devil Trigger за спиной, они выглядят почти как твой фиолетовый дух!",
                "Хм. Боевая проекция твоей собственной воли, способная перехватывать гигантов на лету... По сути, у нас очень близкая сила, Неро.",
                "Только у тебя лицо кирпичом, а я привык вкладывать в каждый хук всю злость без остатка!",
                "Главное, чтобы голова оставалась холодной, когда кулаки горячие. Покажи внизу, на что способен.");

            AddPair(dict, "dmc_nero", "vyper",
                "Эй, ползучая! Я собственными глазами видел, как ты пыталась отвинтить золотую гайку с моего запасного протеза на верстаке!",
                "Да она сама открутилась от вибрации, шеф, я её просто поймала хвостом, чтобы в решётку пола не укатилась!",
                "Ври больше, змеюка! Ещё раз тронешь коробки Нико — прокачу верхом на ракетном кулаке вокруг орбиты!",
                "Поняла-поняла, к чужим железным рукам — ни ногой, то есть ни хвостом! Идём лучше монстров трясти!");

            AddPair(dict, "dmc_nero", "haze",
                "От твоего вкрадчивого голоса в сон клонит сильнее, чем от старых проповедей Ордена Меча, честное слово...",
                "На тех проповедях вы демонстративно надевали наушники с музыкой, не так ли, Неро? Чудесная защитная привычка.",
                "Воу, откуда ты и такие мелочи знаешь?! Ладно, в бою усыпляй самых жирных тварей, а будить их буду я — ударом об землю!",
                "Резкое пробуждение через суплекс... Неортодоксально, но крайне эффективно.");

            // Iconic Counterpart Rivalry #4: DMC Dante + Nero (3 distinct conversations!)
            AddPair(dict, "dmc_nero", "dmc_trio",
                "Так, старик, давай договоримся на берегу перед всем экипажем: ещё РАЗ назовёшь меня «мёртвым грузом» — полетишь на Луну без капсулы!",
                "Аха-ха-ха! Господи, малец, сколько времени прошло, а ты до сих пор припоминаешь мне одну невинную фразу в пылу драки?!",
                "Я тебе той фразой поперёк рожи потом вмазал и батю твоего разнял, если запамятовал на старости лет!",
                "Помню-помню, зубы до сих пор ноют от гордости за племянника! Ладно, номер один — показывай класс на высадке!");

            AddPair(dict, "dmc_trio", "dmc_nero",
                "Слушай, Неро, а вывеску «Devil May Cry» на твоём фургоне всё ещё видно издалека, или Нико совсем заклеила её рекламой оружия?",
                "Неоновая вывеска сияет как новенькая, дядя! В отличие от твоей конторы, мы хотя бы исправно платим за электричество!",
                "Удар ниже пояса! Зато в филиале у меня теперь семейный подряд — глядишь, и с этой планеты привезём чем закрыть счета!",
                "Ага, если ты опять не спустишь всю долю на пиццу в корабельном буфете раньше посадки!");

            AddPair(dict, "dmc_nero", "dmc_trio",
                "Эй, Данте... спрошу серьёзно: этот лунный король Митрикс по силе тянет на Уризена, или мы справимся вдвоём без лишней драмы?",
                "Большой парень с молотком и комплексом бога? Разогреемся на первых трёх фазах, а на четвёртой устроим ему семейный джекпот!",
                "Хех! Вот за эту наглую уверенность с тобой и невозможно спорить дольше минуты! Завожу «Алую Королеву»!",
                "Красавчик! Кто наберёт меньше очков стиля до Телепорта — тот сегодня дежурит у раковины!");

            AddPair(dict, "dmc_nero", "sanabi",
                "Вот это я понимаю — армейский цепной гарпун во всю руку! Генерал, как вы выдерживаете такой рывок плечевым суставом без магии?!",
                "Генерал: Титановый каркас в ключице и тридцать лет практики, сынок. — Мари: А у вас рука на реактивной тяге И меч с мотоциклетной ручкой — полный улет!",
                "Ха! Мари, мы бы с тобой и Нико за вечер собрали такой крюк на турбине, что твой батя обгонял бы истребители!",
                "Мари: ПАПА, СЛЫШАЛ?! Нам срочно нужен бензиновый ускоритель в локоть! — Генерал: ...Нико к моему протезу не подпускать на пушечный выстрел.");

            AddPair(dict, "dmc_nero", "sol_ky",
                "Подожди-ка... Белый рыцарский мундир, священный орден, правильные речи... Клянусь, у меня сейчас вьетнамские флешбэки из Фортуны!",
                "Прошу, не тревожьтесь, Неро — я наслышан о фанатиках вашего Ордена Меча и презираю тех, кто прикрывает жестокость верой.",
                "Фух... По глазам вижу, что не врёшь. Да и бьёшь ты честно, лицом к лицу, без грязных алхимических опытов.",
                "Честь рыцаря существует лишь для защиты людей, юный друг. Буду рад сражаться рядом с вами.");

            AddPair(dict, "dmc_nero", "lappland_decadenza",
                "Вся в чёрном с золотом, командуешь стаей призрачных волков и смеёшься как на опере... Ты случайно не знакомая Ви?",
                "Ах, тот бледный юноша со стихами Блейка и говорящей птицей? Увы, мы не представлены, но вкус к драме я оценила бы!",
                "Слава богу, одной говорящей курицы Грифона мне хватило на всю жизнь! Хотя твои волки рвут демонов куда бодрее!",
                "Благодарю за пылкий комплимент, юный охотник! Выходите на авансцену — оркестр за вами!");

            AddPair(dict, "dmc_nero", "w_wisadel",
                "Эй, Вишадель, твои летающие пушки с призраками лупят так плотно, что я едва успеваю выдернуть монстра крюком из огня!",
                "Так не таскай еду из моей тарелки, мальчик с мотором! Кого накрыл мой пилон — тот уже записан в графу «пепел»~",
                "Ну уж нет, без хорошего мордобоя вблизи у меня шкала стиля остывает! Оставляй хотя бы боссов на растерзание!",
                "Ладно, горячая голова: я сношу свиту одним залпом, а главный здоровяк — целиком твой!");

            // =========================================================================
            // ALT 5: DMC_VERGIL (Вергилий) vs 31 base + sol_ky, lappland_decadenza, w_wisadel, dmc_nero (35 пар!)
            // =========================================================================
            AddPair(dict, "dmc_vergil", "commando",
                "Огнестрельное оружие... Шумный и лишённый изящества костыль для тех, кому не хватает собственной силы, солдат.",
                "Костыль или нет, Вергилий, а двести выстрелов в минуту стабильно держат периметр чистым.",
                "...Хм. Твоя выдержка под натиском превосходящего врага заслуживает доли уважения. Не путайся на линии моего разреза.",
                "Принято. Вы режете пространство впереди, я зачищаю фланги.");

            AddPair(dict, "dmc_vergil", "artificer",
                "Высший Суд мнит, будто способен измерить пределы мироздания приборами. Истинная мощь не укладывается в таблицы, женщина.",
                "И всё же твоя катана «Ямато» сворачивает метрику пространства строго по уравнениям кротовых нор, Вергилий.",
                "Любопытная трактовка для смертного ума. Посмотрим, поспеет ли твоя плазма за моим Judgment Cut.",
                "Сингулярность клинка и термоядерный импульс — проверим эту теорию на стражах Телепорта.");

            AddPair(dict, "dmc_vergil", "huntress",
                "Лишних движений нет, дыхание ровное, взгляд прикован к уязвимой точке. В тебе есть настоящая концентрация, лучница.",
                "Ты рассекаешь цель, даже не сходя с места, Вергилий, а я живу в постоянном беге. Два полюса одной охоты.",
                "Неподвижный центр бури и стремительный ветер по краям. Достойное сочетание.",
                "Тогда я выманиваю стаю на открытый круг, а ты закрываешь ножны.");

            AddPair(dict, "dmc_vergil", "buzz",
                "Ты облачился в нелепые яркие доспехи и кричишь лозунги перед боем. Где твоя истинная мотивация, «рейнджер»?",
                "Моя мотивация — защита мирных миров Галактического Альянса от тиранов и хаоса, гражданин в синем плаще!",
                "...Наивный идеализм. Впрочем, если он позволяет тебе без страха бросаться на титанов — пусть так.",
                "Рад, что мы достигли взаимопонимания! Держу воздушное прикрытие!");

            AddPair(dict, "dmc_vergil", "v1",
                "Бездушный механизм, созданный лишь для поглощения чужой крови. Жалкая пародия на стремление к совершенству.",
                "[СКАНИРОВАНИЕ КЛИНКА «ЯМАТО» // ПРОСТРАНСТВЕННОЕ СЕЧЕНИЕ ВЫЗЫВАЕТ ОБИЛЬНОЕ КРОВОТЕЧЕНИЕ ЦЕЛЕЙ. ОДОБРЕНО.]",
                "Питаешься объедками с моего клинка, жестянка? Смотри не попади под лезвие в погоне за брызгами.",
                "[БЕЗОПАСНАЯ ДИСТАНЦИЯ РАССЧИТАНА: 0.4 МИЛЛИМЕТРА ОТ ВАШЕГО РАЗРЕЗА.]");

            AddPair(dict, "dmc_vergil", "sol",
                "Красный цвет, грубая сила и необузданное пламя напоказ... Почему мне вечно попадается один и тот же раздражающий типаж?",
                "Тц, а ты вылитый синий пижон с задранным подбородком! Только вместо чая таскаешь катану и бубнишь про какую-то «силу»!",
                "Осторожнее со словами, прототип Гира, иначе я проверю, рассечёт ли «Ямато» твоё первородное пламя.",
                "Попробуй, умник — только потом не жалуйся, когда причёску опалит вулканическим апперкотом!");

            AddPair(dict, "dmc_vergil", "gwen",
                "Две половинки одного целого, сведённые в стальные лезвия... Твои ножницы хранят странное эхо расколотой души.",
                "Вы это почувствовали, Вергилий? Но мои ножницы созданы, чтобы сшивать и защищать мир, а ваш клинок — чтобы разделять!",
                "Иногда, чтобы спасти суть, необходимо безжалостно отсечь лишнюю слабость. Таков закон «Ямато».",
                "И всё же я верю, что однажды две половинки снова обретут покой — как обрели и вы.");

            AddPair(dict, "dmc_vergil", "enforcer",
                "Прятаться за глухим щитом и ждать чужого удара — путь того, кто смирился с обороной, солдат.",
                "Щит бережёт силы до той самой секунды, когда враг откроется под ответный выстрел в упор, Вергилий.",
                "Хм. Терпение перед неотвратимым контрударом по принципу иайдзюцу... В этом есть здравое зерно.",
                "Держу центр. Режьте их, когда отскочат от моей брони.");

            AddPair(dict, "dmc_vergil", "scout",
                "Ты производишь столько шума, звона и пустой бравады, гном, что распугиваешь дичь за три долины вперёд.",
                "Эй, синий господин, в пещерах без крика «Скала и Камень» боевой дух падает! Хочешь, и тебе бороду для солидности заплету?",
